// -----------------------------------------------------------------------------
// File        : uart_apb_props.v
// Description : Formal properties for uart_apb, derived only from the
//               specification SPEC-UART-APB-1.0 (spec/requirements.json).
//               Immediate assert/assume for Yosys read_verilog -formal and
//               k-induction (sat -tempinduct, max 20 steps).
// Author      : Generated by AI agent (formal-engineer)
// Date        : 2026-11-17
// -----------------------------------------------------------------------------
// Structure
//   * Stateless APB decode checks (REQ-2/3/4/5/16/22): checked in every cycle
//     after the first reset edge. They depend only on bus inputs and decode.
//   * Reset-anchored window checks: a shadow model (CTRL, BAUD, TX FIFO
//     occupancy, first TX frame) is exact only for WIN cycles after a reset
//     edge. Bounding the window below the induction depth keeps every
//     property k-inductive without referring to DUT internals (which the
//     formal engineer may not read).
//   * Within the window no RX frame can complete (a frame lasts >= 37 cycles
//     for D >= DIV_MIN), so RX_EMPTY=1, RX_FULL=0 and STATUS[7:5]=0 are exact.
// Assumptions: only the APB protocol rules of REQ-2 (m_* below).
// No reset assumption: every check is gated by "a reset edge has been seen".
// -----------------------------------------------------------------------------
module uart_apb_props (
  input wire        clk,
  input wire        rst_n,
  input wire        psel,
  input wire        penable,
  input wire        pwrite,
  input wire [4:0]  paddr,
  input wire [31:0] pwdata,
  input wire        rxd
);
  localparam integer FIFO_DEPTH = 4;           // spec parameter
  localparam [15:0]  DIV_RESET  = 16'd868;     // spec parameter
  localparam [15:0]  DIV_MIN    = 16'd4;       // spec parameter
  localparam [4:0]   WIN        = 5'd16;       // window length (cycles after reset)

  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;
  wire        txd;
  wire        irq;

  uart_apb dut (
    .clk(clk), .rst_n(rst_n), .psel(psel), .penable(penable), .pwrite(pwrite),
    .paddr(paddr), .pwdata(pwdata), .prdata(prdata), .pready(pready),
    .pslverr(pslverr), .rxd(rxd), .txd(txd), .irq(irq));

  // ---------------------------------------------------------------------------
  // Previous-cycle copies of the inputs
  // ---------------------------------------------------------------------------
  reg        psel_q    = 1'b0;
  reg        penable_q = 1'b0;
  reg        pwrite_q  = 1'b0;
  reg        rst_q     = 1'b0;
  reg [4:0]  paddr_q   = 5'd0;
  reg [31:0] pwdata_q  = 32'd0;

  always @(posedge clk) begin
    psel_q    <= psel;
    penable_q <= penable;
    pwrite_q  <= pwrite;
    rst_q     <= rst_n;
    paddr_q   <= paddr;
    pwdata_q  <= pwdata;
  end

  // ---------------------------------------------------------------------------
  // Environment assumptions (REQ-2: non-protocol bus inputs are undefined)
  // ---------------------------------------------------------------------------
  always @(*) begin
    // m_apb_setup_before_access: penable=1 only after a setup cycle (REQ-2)
    if (penable) assume (psel_q && !penable_q);
    // m_apb_stable_ctrl: paddr/pwrite (and pwdata for writes) stable from setup to access (REQ-2)
    if (psel && penable) begin
      assume (paddr == paddr_q);
      assume (pwrite == pwrite_q);
      if (pwrite) assume (pwdata == pwdata_q);
    end
  end

  // ---------------------------------------------------------------------------
  // Decode (paddr[1:0] ignored: REQ-3)
  // ---------------------------------------------------------------------------
  wire       acc  = psel && penable;               // access cycle
  wire [2:0] widx = paddr[4:2];
  wire       a_tx = (widx == 3'd0);                // 0x00 TXDATA
  wire       a_rx = (widx == 3'd1);                // 0x04 RXDATA
  wire       a_st = (widx == 3'd2);                // 0x08 STATUS
  wire       a_ct = (widx == 3'd3);                // 0x0C CTRL
  wire       a_bd = (widx == 3'd4);                // 0x10 BAUD
  wire       a_um = (widx >= 3'd5);                // 0x14..0x1F unmapped

  reg        seen = 1'b0;                          // a reset edge has been observed
  // Valid access: setup and access cycle both outside reset, after the first reset.
  wire       vacc = acc && rst_n && rst_q && seen;
  wire       vrd  = vacc && !pwrite;
  wire       vwr  = vacc && pwrite;

  // ---------------------------------------------------------------------------
  // Reset-anchored shadow model
  // ---------------------------------------------------------------------------
  reg [4:0]  age         = 5'd0;    // edges since the last reset edge, saturates at WIN
  reg [6:0]  ctrl_sh     = 7'd0;    // CTRL[6:0]
  reg [15:0] baud_sh     = 16'd0;   // BAUD[15:0]
  reg [2:0]  tx_hi       = 3'd0;    // upper bound of TX FIFO occupancy (exact if tx_exact)
  reg        tx_exact    = 1'b0;    // no TX pop can have happened since reset
  reg        pushed      = 1'b0;    // at least one byte accepted into the TX FIFO
  reg [7:0]  byte0       = 8'd0;    // first byte accepted since reset
  reg        txen_q      = 1'b0;    // TX_EN in the previous cycle (0 after reset)
  reg [1:0]  pend_q      = 2'd0;    // consecutive earlier cycles with a start pending
  reg        started     = 1'b0;    // first frame since reset has started
  reg [15:0] d_sh        = 16'd0;   // D of that frame (BAUD at its first start cycle)
  reg [3:0]  idx         = 4'd0;    // bit index: 0 start, 1..8 data bits
  reg [15:0] cyc         = 16'd0;   // 1-based cycle number inside the current bit
  reg [1:0]  busy_left   = 2'd0;    // cycles left after a STATUS read made before any frame
  reg        busy_bit    = 1'b0;    // TX_BUSY value returned by that read
  reg        exp_irq_q   = 1'b0;    // expected irq in the previous cycle
  reg        exp_known_q = 1'b0;    // exp_irq_q is determined by the model

  wire       win        = seen && (age < WIN);
  wire       txen       = ctrl_sh[0];
  wire       push       = vwr && a_tx;
  wire [6:0] ctrl_nx    = (vwr && a_ct) ? pwdata[6:0] : ctrl_sh;
  // A start bit is legal only if a byte was pushed and TX_EN=1 in this or the
  // previous cycle (REQ-10, REQ-11); only the first frame after reset is tracked.
  wire       start_now  = win && !started && !txd;
  wire       start_ok   = pushed && (txen || txen_q);
  wire       in_frame   = started || start_now;
  wire       cond       = txen && pushed && !started;   // REQ-10 start condition
  // irq model inside the window: RX terms and error terms are 0 (no RX frame can
  // complete), so irq depends on IE_TXE and TX_EMPTY only (REQ-23).
  wire       tx_empty_k = tx_exact || (tx_hi == 3'd0);
  wire       exp_known  = !ctrl_sh[5] || tx_empty_k;
  wire       exp_irq    = ctrl_sh[5] && (tx_hi == 3'd0);

  reg        exp_bit;
  always @(*) begin
    case (idx)
      4'd0:    exp_bit = 1'b0;          // start bit
      4'd1:    exp_bit = byte0[0];      // data bits, LSB first
      4'd2:    exp_bit = byte0[1];
      4'd3:    exp_bit = byte0[2];
      4'd4:    exp_bit = byte0[3];
      4'd5:    exp_bit = byte0[4];
      4'd6:    exp_bit = byte0[5];
      4'd7:    exp_bit = byte0[6];
      default: exp_bit = byte0[7];
    endcase
  end

  always @(posedge clk) begin
    if (!rst_n) begin
      seen        <= 1'b1;
      age         <= 5'd0;
      ctrl_sh     <= 7'd0;
      baud_sh     <= DIV_RESET;
      tx_hi       <= 3'd0;
      tx_exact    <= 1'b1;
      pushed      <= 1'b0;
      byte0       <= 8'd0;
      txen_q      <= 1'b0;
      pend_q      <= 2'd0;
      started     <= 1'b0;
      d_sh        <= 16'd0;
      idx         <= 4'd0;
      cyc         <= 16'd0;
      busy_left   <= 2'd0;
      busy_bit    <= 1'b0;
      exp_irq_q   <= 1'b0;
      exp_known_q <= 1'b1;
    end else begin
      // An access whose setup cycle was in reset is outside the scope of the
      // model (REQ-1/REQ-2 conflict, see report): close the window.
      if (acc && !rst_q)
        age <= WIN;
      else if (age < WIN)
        age <= age + 5'd1;
      txen_q      <= txen;
      exp_irq_q   <= exp_irq;
      exp_known_q <= exp_known;
      if (vwr && a_ct)
        ctrl_sh <= pwdata[6:0];
      if (vwr && a_bd && (pwdata[15:0] >= DIV_MIN))
        baud_sh <= pwdata[15:0];
      if (push) begin
        if (tx_hi != FIFO_DEPTH) tx_hi <= tx_hi + 3'd1;
        if (!pushed) byte0 <= pwdata[7:0];
        pushed <= 1'b1;
      end
      // A pop may happen once TX_EN=1 while the FIFO holds (or receives) a byte.
      if ((txen || ctrl_nx[0]) && ((tx_hi != 3'd0) || push))
        tx_exact <= 1'b0;
      if (cond)
        pend_q <= (pend_q == 2'd3) ? 2'd3 : pend_q + 2'd1;
      else
        pend_q <= 2'd0;
      // first-frame tracker
      if (start_now) begin
        started <= 1'b1;
        d_sh    <= baud_sh;
        if (baud_sh <= 16'd1) begin
          idx <= 4'd1;
          cyc <= 16'd1;
        end else begin
          idx <= 4'd0;
          cyc <= 16'd2;
        end
      end else if (started) begin
        if (cyc >= d_sh) begin
          idx <= (idx == 4'd15) ? 4'd15 : idx + 4'd1;
          cyc <= 16'd1;
        end else begin
          cyc <= cyc + 16'd1;
        end
      end
      // STATUS read before any frame: if it returned TX_BUSY=1, a start bit must
      // follow within 3 cycles (checked by a_busy_pre)
      if (win && vrd && a_st && !in_frame) begin
        busy_left <= 2'd3;
        busy_bit  <= prdata[4];
      end else if (busy_left != 2'd0) begin
        busy_left <= busy_left - 2'd1;
        if (in_frame) busy_bit <= 1'b0;
      end
    end
  end

  // ---------------------------------------------------------------------------
  // Stateless assertions (every cycle after the first reset edge)
  // ---------------------------------------------------------------------------
  always @(posedge clk) begin
    if (seen) begin
      a_pready_one:      assert (pready == 1'b1);                         // REQ-2
      if (!(acc && !pwrite))
        a_prdata_idle:   assert (prdata == 32'd0);                        // REQ-2
      if (!acc)
        a_pslverr_idle:  assert (pslverr == 1'b0);                        // REQ-2
    end
    if (vrd && a_tx)
      a_rd_txdata:       assert (prdata == 32'd0 && !pslverr);            // REQ-3
    if (vwr && a_rx)
      a_wr_rxdata:       assert (pslverr == 1'b0);                        // REQ-3
    if (vacc && a_ct)
      a_ctrl_noerr:      assert (pslverr == 1'b0);                        // REQ-3 REQ-5
    if (vrd && a_ct)
      a_ctrl_upper0:     assert (prdata[31:7] == 25'd0);                  // REQ-3
    if (vrd && a_bd)
      a_baud_rd:         assert (prdata[31:16] == 16'd0 && !pslverr);     // REQ-3
    if (vwr && a_bd)
      a_baud_wr_err:     assert (pslverr == (pwdata[15:0] < DIV_MIN));    // REQ-22
    if (vacc && a_st)
      a_status_noerr:    assert (pslverr == 1'b0);                        // REQ-3 REQ-5
    if (vrd && a_st)
      a_status_upper0:   assert (prdata[31:8] == 24'd0);                  // REQ-5
    if (vacc && a_um)
      a_unmapped_err:    assert (pslverr == 1'b1);                        // REQ-4
    if (vrd && a_um)
      a_unmapped_rd0:    assert (prdata == 32'd0);                        // REQ-4
    if (vrd && a_rx)
      a_rxdata_upper0:   assert (prdata[31:8] == 24'd0);                  // REQ-16
  end

  // ---------------------------------------------------------------------------
  // Reset-anchored window assertions
  // ---------------------------------------------------------------------------
  always @(posedge clk) begin
    if (win) begin
      // cycle after the reset edge
      if (age == 5'd0) begin
        a_rst_txd:       assert (txd == 1'b1);                            // REQ-1
        a_rst_irq:       assert (irq == 1'b0);                            // REQ-1
        if (!acc)
          a_rst_bus:     assert (prdata == 32'd0 && !pslverr);            // REQ-1
      end
      // register read-back against the shadow (reset values and writes)
      if (vrd && a_ct)
        a_ctrl_val:      assert (prdata == {25'd0, ctrl_sh});             // REQ-1 REQ-3 REQ-4
      if (vrd && a_bd)
        a_baud_val:      assert (prdata == {16'd0, baud_sh});             // REQ-1 REQ-22 REQ-4
      // RX FIFO is empty in the window: read gives 0 + error, nothing changes
      if (vrd && a_rx)
        a_rx_empty_rd:   assert (prdata == 32'd0 && pslverr);             // REQ-16
      if (vrd && a_st) begin
        a_st_err0:       assert (prdata[7:5] == 3'b000);                  // REQ-1 REQ-20
        a_st_rxflags:    assert (prdata[3] && !prdata[2]);                // REQ-1 REQ-7
        if (tx_exact)
          a_st_txfull:   assert (prdata[0] == (tx_hi == FIFO_DEPTH));     // REQ-7 REQ-5
        if (tx_exact)
          a_st_txempty:  assert (prdata[1] == (tx_hi == 3'd0));           // REQ-7 REQ-1
        if (tx_hi != FIFO_DEPTH)
          a_st_notfull:  assert (!prdata[0]);                             // REQ-7
        if (tx_hi == 3'd0)
          a_st_empty:    assert (prdata[1]);                              // REQ-7
        if (in_frame)
          a_st_busy:     assert (prdata[4]);                              // REQ-12
      end
      // TX push accept / drop
      if (push && tx_hi != FIFO_DEPTH)
        a_tx_push_ok:    assert (pslverr == 1'b0);                        // REQ-6
      if (push && tx_exact && tx_hi == FIFO_DEPTH)
        a_tx_push_full:  assert (pslverr == 1'b1);                        // REQ-6
      // TX_BUSY may precede a start bit by at most 3 cycles
      if (busy_left == 2'd1)
        a_busy_pre:      assert (!busy_bit || in_frame);                  // REQ-12
      // txd idle unless a legal start; start no later than 3 cycles after the event
      if (start_now)
        a_tx_start_ok:   assert (start_ok);                               // REQ-10 REQ-11
      if (cond)
        a_tx_start_by:   assert (pend_q != 2'd3 || !txd);                 // REQ-10
      // frame contents and bit timing (start bit, data LSB first, D cycles per bit)
      if (started && idx <= 4'd8)
        a_tx_bits:       assert (txd == exp_bit);                         // REQ-8 REQ-9 REQ-6
      // interrupt equation with at most one cycle of lag
      if (age != 5'd0 && exp_known && exp_known_q)
        a_irq_eq:        assert (irq == exp_irq || irq == exp_irq_q);     // REQ-23
    end
  end
endmodule
